'use strict';
const $=id=>document.getElementById(id),C=GeometryCore;let data,state,key,group,bounds,selected=null;const cam={yaw:-35,pitch:25,zoom:1};const hits={};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const f=(v,n=2)=>Number(v).toFixed(n),pct=v=>f(v*100)+'%',signed=v=>(v>=0?'+':'')+pct(v);
function status(s){$('supplementStatus').textContent=s;}
function save(){try{localStorage.setItem(key,JSON.stringify(state));status('补充判断已保存在本浏览器；导出后发回对话。原9组回执未改动。');}catch(e){status('本地保存不可用，请导出回执备份。');}}
function drawOne(canvas,g){const rect=canvas.getBoundingClientRect(),w=rect.width,h=rect.height,dpr=window.devicePixelRatio||1;canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);const proj=p=>C.project(p,bounds,cam,w,h);hits[canvas.id]=[];
 function line(a,b,color,width=1,dash=[]){const p=proj(a),q=proj(b);ctx.beginPath();ctx.setLineDash(dash);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.stroke();ctx.setLineDash([]);}
 const radius=bounds.radius,cy=-1;for(let i=-4;i<=4;i++){const t=i*radius/4;line([bounds.center[0]-radius,cy,bounds.center[2]+t],[bounds.center[0]+radius,cy,bounds.center[2]+t],'#e2e8ed');line([bounds.center[0]+t,cy,bounds.center[2]-radius],[bounds.center[0]+t,cy,bounds.center[2]+radius],'#e2e8ed');}
 function ring(r,color,ref){const n=r.bottom.length;if(!ref&&$('showFaces').checked){const faces=r.bottom.map((a,i)=>{const j=(i+1)%n;const ps=[a,r.bottom[j],r.top[j],r.top[i]].map(proj);return{ps,d:ps.reduce((s,p)=>s+p.depth,0)/4};}).sort((a,b)=>a.d-b.d);for(const face of faces){ctx.beginPath();face.ps.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fillStyle='rgba(9,118,135,.10)';ctx.fill();}}
 for(let i=0;i<n;i++){const j=(i+1)%n,dash=ref?[5,4]:[];line(r.bottom[i],r.bottom[j],color,ref?1.6:2.3,dash);line(r.bottom[i],r.top[i],color,ref?1.4:2,dash);if($('showTop').checked)line(r.top[i],r.top[j],color,ref?1.6:2.3,dash);}
 for(let i=0;i<n;i++){for(const [which,p3] of [['bottom',r.bottom[i]],['top',r.top[i]]]){if(which==='top'&&!$('showTop').checked)continue;const p=proj(p3);const active=selected&&selected.label===(ref?'参考':g.label)&&selected.index===i;ctx.beginPath();ctx.fillStyle=active?'#df9c00':color;ctx.arc(p.x,p.y,active?6:3,0,Math.PI*2);ctx.fill();if(!ref)hits[canvas.id].push({x:p.x,y:p.y,index:i,label:g.label});if($('showNumbers').checked&&which==='top'){const text=(ref?'G':'')+(i+1);ctx.font='bold 13px sans-serif';ctx.lineWidth=4;ctx.strokeStyle='white';ctx.strokeText(text,p.x+5,p.y-7);ctx.fillStyle=color;ctx.fillText(text,p.x+5,p.y-7);}}}}
 if(!$('onlyReference').checked)ring(g,'#087586',false);if($('showReference').checked||$('onlyReference').checked)ring(group.reference,'#bb326e',true);
 // Camera marker in the same physical coordinate system.
 const origin=proj([0,0,0]);ctx.strokeStyle='#303d45';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(origin.x-5,origin.y);ctx.lineTo(origin.x+5,origin.y);ctx.moveTo(origin.x,origin.y-5);ctx.lineTo(origin.x,origin.y+5);ctx.stroke();ctx.font='12px sans-serif';ctx.fillStyle='#45535d';ctx.fillText('相机',origin.x+7,origin.y+13);
 const scale=C.project(bounds.center,bounds,cam,w,h).scale;ctx.strokeStyle='#4c606b';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(18,h-25);ctx.lineTo(18+scale,h-25);ctx.stroke();ctx.fillText('1 h',18,h-33);ctx.fillText('同步正交投影 · 不单独缩放',18,23);
}
function draw(){if(!group)return;drawOne($('canvasA'),group.cases[0]);drawOne($('canvasB'),group.cases[1]);$('yawRange').value=cam.yaw;$('pitchRange').value=cam.pitch;$('zoomRange').value=cam.zoom;}
function chooseCorner(label,index){selected={label,index};const g=group.cases.find(x=>x.label===label);const p=g.corners[index];$('selectedCorner').textContent=label+' 角点 '+(index+1)+'：内角 '+f(p.interior_angle)+'°；墙高 '+f(p.height,4)+' h；出边偏离本作答最佳正交轴 '+f(p.axis_deviation)+'°。';document.querySelectorAll('[data-corner]').forEach(el=>el.classList.toggle('highlight',el.dataset.label===label&&+el.dataset.corner===index));draw();}
function bindCanvas(canvas){let drag=null;canvas.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,total:0};canvas.setPointerCapture(e.pointerId);};canvas.onpointermove=e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;drag.total+=Math.abs(dx)+Math.abs(dy);cam.yaw=((cam.yaw+dx*.45+540)%360)-180;cam.pitch=Math.max(-89,Math.min(90,cam.pitch+dy*.35));drag.x=e.clientX;drag.y=e.clientY;draw();};canvas.onpointerup=e=>{if(drag&&drag.total<5){const r=canvas.getBoundingClientRect();const h=(hits[canvas.id]||[]).map(p=>({...p,d:Math.hypot(p.x-(e.clientX-r.left),p.y-(e.clientY-r.top))})).sort((a,b)=>a.d-b.d)[0];if(h&&h.d<18)chooseCorner(h.label,h.index);}drag=null;if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);};canvas.onpointercancel=()=>{drag=null;};canvas.onlostpointercapture=()=>{drag=null;};canvas.addEventListener('wheel',e=>{e.preventDefault();cam.zoom=Math.max(.6,Math.min(3,cam.zoom*Math.exp(-e.deltaY*.001)));draw();},{passive:false});canvas.onkeydown=e=>{const acts={ArrowLeft:()=>cam.yaw-=5,ArrowRight:()=>cam.yaw+=5,ArrowUp:()=>cam.pitch=Math.min(90,cam.pitch+5),ArrowDown:()=>cam.pitch=Math.max(-89,cam.pitch-5),'+':()=>cam.zoom=Math.min(3,cam.zoom+.1),'-':()=>cam.zoom=Math.max(.6,cam.zoom-.1)};if(acts[e.key]){e.preventDefault();acts[e.key]();cam.yaw=((cam.yaw+540)%360)-180;draw();}};}
function choices(){const a=state.answers[group.id];$('supplementChoices').innerHTML=C.choices.map(v=>'<button data-choice="'+esc(v)+'" aria-pressed="'+(a.choice===v)+'" class="'+(a.choice===v?'selected':'')+'">'+esc(v)+'</button>').join('');document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{a.choice=a.choice===b.dataset.choice?null:b.dataset.choice;a.updated_at=new Date().toISOString();save();choices();nav();});$('supplementComment').value=a.comment;}
function nav(){$('groupNav').innerHTML=data.groups.map(g=>'<button class="'+(g.id===group.id?'selected':'')+'" data-group="'+g.id+'">'+g.id+' '+(state.answers[g.id].choice?'✓':'○')+'</button>').join('');document.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>openGroup(b.dataset.group));}
function openGroup(id){group=data.groups.find(g=>g.id===id);bounds=C.bounds(group);selected=null;Object.assign(cam,{yaw:-35,pitch:25,zoom:1});$('groupTitle').textContent=group.id+' · A / B 同图对照';$('selectedCorner').textContent='没有选中角点。顶部连线按各角点真实高度绘制，不将顶面填成一个平面。';if(!state.answers[id].first_viewed_at){state.answers[id].first_viewed_at=new Date().toISOString();save();}
 const rows=[['曼哈顿方向偏差 D','D',v=>f(v)+'°'],['底面面积','area',v=>f(v,3)+' h²'],['面积 / 参考面积','area_ratio',pct],['底面 IoU','floor_iou',pct],['缺少区域 / 参考面积','missing_reference_fraction',pct],['多出区域 / 参考面积','extra_reference_fraction',pct],['平均墙高','mean_height',v=>f(v,4)+' h'],['整体高度相对参考差异','height_bias_relative',signed],['自身高度标准差 / 参考平均高','height_std_relative',pct],['最高－最低 / 参考平均高','height_range_relative',pct]];
 $('summaryTable').innerHTML='<table><thead><tr><th>诊断量（非总分）</th><th>A</th><th>B</th></tr></thead><tbody>'+rows.map(([name,k,fmt])=>'<tr><td>'+name+'</td>'+group.cases.map(g=>'<td>'+fmt(g[k])+'</td>').join('')+'</tr>').join('')+'</tbody></table><p>参考底面面积 '+f(group.reference.area,3)+' h²；参考平均墙高 '+f(group.reference.mean_height,4)+' h；参考高度极差 '+f(group.reference.height_range,6)+' h。</p>';
 $('cornerTables').innerHTML=group.cases.map(g=>'<section><h3>'+g.label+' · 逐角点与出边</h3><table><thead><tr><th>角点</th><th>内角°</th><th>墙高 h</th><th>出边长 h</th><th>轴偏差°</th></tr></thead><tbody>'+g.corners.map((p,i)=>'<tr tabindex="0" data-label="'+g.label+'" data-corner="'+i+'"><td>'+(i+1)+'</td><td>'+f(p.interior_angle)+'</td><td>'+f(p.height,4)+'</td><td>'+f(p.outgoing_length,3)+'</td><td>'+f(p.axis_deviation)+'</td></tr>').join('')+'</tbody></table></section>').join('');document.querySelectorAll('[data-corner]').forEach(el=>{el.onclick=()=>chooseCorner(el.dataset.label,+el.dataset.corner);el.onkeydown=e=>{if(e.key==='Enter')el.click();};});
 $('photoViews').innerHTML=[['原图',group.original],['输入点位与处理后结果（与原工作台一致）',group.processed],['局部细节',group.details]].map(([name,src])=>'<details '+(name==='局部细节'?'open':'')+'><summary>'+name+'</summary><img loading="lazy" src="'+src+'" alt="'+group.id+' '+name+'"></details>').join('');document.querySelectorAll('#photoViews img').forEach(img=>img.onclick=()=>{$('largePicture').src=img.src;$('pictureDialog').showModal();});nav();choices();draw();}
for(const id of ['canvasA','canvasB'])bindCanvas($(id));for(const id of ['showReference','showNumbers','showFaces','showTop','onlyReference'])$(id).onchange=draw;for(const [id,k]of [['yawRange','yaw'],['pitchRange','pitch'],['zoomRange','zoom']])$(id).oninput=e=>{cam[k]=+e.target.value;draw();};document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{Object.assign(cam,({iso:{yaw:-35,pitch:25,zoom:1},top:{yaw:0,pitch:90,zoom:1},front:{yaw:0,pitch:0,zoom:1},side:{yaw:90,pitch:0,zoom:1}})[b.dataset.view]);draw();});$('closePicture').onclick=()=>$('pictureDialog').close();$('supplementComment').oninput=e=>{if(!state)return;state.answers[group.id].comment=e.target.value;state.answers[group.id].updated_at=new Date().toISOString();save();};$('clearSupplement').onclick=()=>{state.answers[group.id].choice=null;state.answers[group.id].updated_at=new Date().toISOString();save();choices();nav();};
$('exportSupplement').onclick=()=>{if(!state)return;const url=URL.createObjectURL(new Blob([JSON.stringify(C.receipt(state),null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='几何数值辅助复核_'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status('已生成补充回执，请将JSON发回对话。');};$('importSupplement').onclick=()=>$('supplementFile').click();$('supplementFile').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>2000000)throw Error('文件过大。');const next=C.validate(JSON.parse(await f.text()),data);if(Object.values(state.answers).some(a=>a.choice!==null||a.comment)&&!confirm('导入会替换本页补充判断，原工作台回执不受影响。继续？'))return;state=next;save();openGroup(group.id);}catch(e){status(e.message);}finally{$('supplementFile').value='';}};
new ResizeObserver(draw).observe($('canvasA'));new ResizeObserver(draw).observe($('canvasB'));
fetch('geometry-data.json').then(r=>{if(!r.ok)throw Error('几何数据读取失败');return r.json();}).then(d=>{data=d;key='quality-geometry-supplement:'+d.dataset_id;state=C.fresh(d);try{const old=localStorage.getItem(key);if(old)state=C.validate(JSON.parse(old),d);}catch(e){status('旧缓存读取失败，未恢复。请导入已导出的补充回执。');}openGroup('C02');}).catch(e=>status(e.message));
